# mitm plugin template

#-----------------------MITM Hooks I/O-------------------------
/*
#如何使用插件参数？

## 例如，如果你设置了一个参数为 url_keyword 的参数，可以通过 MITM_PARAMS 来使用它！
urlKeyword = MITM_PARAMS["url_keyword"]

# 如何输出给 Yakit 给用户查看？

yakit_output(i: any) // 可以只输出到 "Console 界面"
yakit_save(i: any)   // 可以输出并保存到数据库中，在 "插件输出" 中查看
*/
#----------------MITM Hooks Test And Quick Debug-----------------
/*
# __test__ 是 yakit mitm 插件用于调试的函数 【注意：这个函数在 MITM hooks劫持环境下不会被导入】

在这个函数中，你可以使用 yakit.GenerateYakitMITMHooksParams(method: string, url: string, opts ...http.Option) 来方便的生成可供 hooks 调用的参数，参考代码模版中的用法～

*/


#--------------------------WORKSPACE-----------------------------
__test__ = func() {


    results, err := yakit.GenerateYakitMITMHooksParams("GET", "https://blog.csdn.net/rank/list/admin?h=user",)
    if err != nil {
        return
    }
    isHttps, url, reqRaw, rspRaw, body = results

    mirrorHTTPFlow(results...)
    mirrorFilteredHTTPFlow(results...)
    mirrorNewWebsite(results...)
    mirrorNewWebsitePath(results...)
    mirrorNewWebsitePathParams(results...)
}


# mirrorHTTPFlow 会镜像所有的流量到这里，包括 .js / .css / .jpg 这类一般会被劫持程序过滤的请求
mirrorHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    
}

# mirrorFilteredHTTPFlow 劫持到的流量为 MITM 自动过滤出的可能和 "业务" 有关的流量，会自动过滤掉 js / css 等流量
mirrorFilteredHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    
}

# mirrorNewWebsite 每新出现一个网站，这个网站的第一个请求，将会在这里被调用！
mirrorNewWebsite = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    
}

# mirrorNewWebsitePath 每新出现一个网站路径，关于这个网站路径的第一个请求，将会在这里被传入回调
mirrorNewWebsitePath = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    
}

#检查是否为敏感字符串
checkParams = func(param/*string */){
    param = str.ToLower(param)
    notice = [".*system.*",".*admin.*",".*upload.*",".*command.*",".*exec.*",".*sql.*",".*select.*"]
    return str.MatchAnyOfRegexp(param,notice...)
}
# 检查是否为敏感参数

checkParams_B = func(param/*string */){
    param = str.ToLower(param)
    notice = [".*user.*",".*id.*",".*member.*",".*number.*",".*card.*"]
    return str.MatchAnyOfRegexp(param,notice...)
}
# mirrorNewWebsitePathParams 每新出现一个网站路径且带有一些参数，参数通过常见位置和参数名去重，去重的第一个 HTTPFlow 在这里被调用
mirrorNewWebsitePathParams = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {

    urlinstance := str.ParseStringUrlToUrlInstance(url)[0]
    urlpath = str.ToLower(urlinstance.Path)
    freq,err := fuzz.HTTPRequest(req, fuzz.https(isHttps))
    die(err)

    # 路径侧检查 -- 测试通过
    if str.Contains(urlpath,"user"){
        //yakit_output("[Dog]正在尝试路径侧垂直越权...")
        newUrlpath = [
            str.ReplaceAll(urlpath,"user","admin"),
            str.ReplaceAll(urlpath,"user","Admin"),
            str.ReplaceAll(urlpath,"user","ADMIN"),
            str.ReplaceAll(urlpath,"user","admin"),
            str.ReplaceAll(urlpath,"user","system"),
            str.ReplaceAll(urlpath,"user","System"),
            str.ReplaceAll(urlpath,"user","SYSTEM")]
        Urlfuzz := freq.FuzzPath(newUrlpath...)
        r_rsp,err := httpool.Pool(Urlfuzz)
        die(err)
        for result := range r_rsp{
            # 判断是否越权成功 判断状态码是否为200 并且 body 是否相同
            header, body = poc.Split(rsp)
            _header, _body = poc.Split(result.ResponseRaw)

            //计算页面相似度
            hm,err := str.CalcSimHashStability(_body,body)

            //yakit_output(string(hm < 0.98))
            if result.Response.StatusCode == 200 && hm < 0.98{
                yakit_save("[Dog] "+url+"可能存在垂直越权!")
                risk.NewRisk(url,risk.title("[Dog]"+urlpath+"可能存在垂直越权"),risk.details(""),risk.type("info-leak"),risk.payload(string(req)+"|||分割符|||"+string(result.Response.Body)))
            }
        }
    }

    if str.Contains(urlpath,"admin"){
        //yakit_output("[Dog]正在尝试路径侧垂直越权...")
        newUrlpath = [
            str.ReplaceAll(urlpath,"admin","system"),
            str.ReplaceAll(urlpath,"admin","System"),
            str.ReplaceAll(urlpath,"admin","SYSTEM")]
        Urlfuzz := freq.FuzzPath(newUrlpath...)
        r_rsp,err := httpool.Pool(Urlfuzz)
        die(err)
        for result = range r_rsp{
            # 判断是否越权成功 判断状态码是否为200 并且 body 是否相同
            header, body = poc.Split(rsp)
            _header, _body = poc.Split(result.ResponseRaw)

            //计算页面相似度
            hm,err := str.CalcSimHashStability(_body,body)
            if result.Response.StatusCode == 200 && hm < 0.98{
                yakit_save("[Dog] "+url+"可能存在垂直越权!")
                risk.NewRisk(url,risk.title("[Dog]"+urlpath+"可能存在垂直越权"),risk.details(""),risk.type("info-leak"),risk.payload(string(req)+"|||分割符|||"+string(result.Response.Body)))
            }
        }
    }


    # 参数侧检查 -- 测试通过
    for _,param := range freq.GetCommonParams(){
        paramName = param.Name()
        originValue = param.Value()
        
        # 检查参数名是否包含敏感字符串 如果 存在 则记录整个req
        if checkParams(paramName) {
            yakit_save("[+]敏感参数名 : " + paramName)
            yakit_status("[Dog]最近的敏感参数",paramName)
            risk.NewRisk(url,risk.title("[Dog]存在敏感参数 :"+ paramName),risk.details(""),risk.type("info-leak"),risk.payload(string(req)))
        }

        //yakit_output(string(string(originValue)=="user"))
        //yakit_output(string(originValue[0]))
        # 检查参数值是否可垂直提权
        if str.HasPrefix(sprint(type(originValue)), "[]") {
            if originValue[0] != undefined {
                originValue = sprint(originValue[0])
            }else{
                originValue = ""
            }
        } else {
            originValue = sprint(originValue)
        }
        if originValue == "user" {
            
            yakit_output("[Dog]正在尝试垂直越权...")
            r = param.Fuzz("admin","Admin","ADMIN","system","System","SYSTEM")
            r_rsp,err := httpool.Pool(r)
            die(err)
            for result := range r_rsp{
                # 判断是否越权成功 简单判断状态码是否为200
                if result.Response.StatusCode == 200 {
                    yakit_save("[Dog] "+url+"可能存在垂直越权!")
                    risk.NewRisk(url,risk.title("[Dog]可能存在垂直越权"),risk.details(""),risk.type("info-leak"),risk.payload(string(req)))
                }
            }

        }
        # 检查参数是否可平行越权
        // if checkParams_B(paramName){
        //     yakit_output("[Dog]正在尝试平行越权...")
        //     # 获取末位
        //     lastValue := originValue[len(originValue)-1:]
        //     replaceValue := ""
        //     if lastValue == "0"{
        //         replaceValue = 1
        // }else{
        //     replaceValue = 1
        // }
        // r = param.Fuzz("replaceValue","")
        // r_rsp,err := httpool.Pool(r)
        // die(err)
        // for result := range r_rsp{
        //     # 判断是否越权成功 判断状态码是否为200 并且 body 是否相同
        //     if result.Response.StatusCode == 200 && len(result.Response.Body)!=len(body){
        //         yakit_save("[Dog]可能存在平行越权！")
        //         risk.NewRisk(url,risk.title("[Dog]可能存在平行越权"),risk.details(""),risk.type("info-leak"),risk.payload(string(req)+"|||分割符|||"+string(result.Response.Body)))
        //     }
        // }
        // }
    }
}
